<?php $situacao = situacao_plano_treino($plano); ?>
<div class="d-flex flex-wrap justify-content-between align-items-start gap-3 mb-4"><div><div class="d-flex align-items-center gap-2"><h1 class="h3 mb-1"><?= escapar($plano['ptr_nome']) ?></h1><span class="badge <?= escapar($situacao['classe']) ?>"><?= escapar($situacao['rotulo']) ?></span></div><p class="text-secondary mb-0"><?= escapar($plano['ptr_objetivo'] ?: 'Plano de treino') ?> · <?= escapar(formatar_data($plano['ptr_data_inicio'])) ?><?= $plano['ptr_data_fim'] ? ' a ' . escapar(formatar_data($plano['ptr_data_fim'])) : ' em diante' ?></p></div><div class="d-flex gap-2"><a class="btn btn-outline-secondary" href="<?= escapar(url('/treinos/planos')) ?>">Voltar</a><a class="btn btn-outline-primary" href="<?= escapar(url('/treinos/planos/formulario?id=' . $plano['ptr_id'])) ?>">Editar plano</a><a class="btn btn-success" href="<?= escapar(url('/treinos/planejados/formulario?plano=' . $plano['ptr_id'])) ?>"><i class="bi bi-plus-lg me-1"></i>Adicionar treino</a></div></div>
