<?php else: ?><div class="vstack gap-4"><?php foreach ($treinos as $treino): ?><section class="card"><div class="card-header bg-white d-flex flex-wrap justify-content-between align-items-center gap-2 py-3"><div><h2 class="h5 mb-0"><?= escapar($treino['trp_nome']) ?></h2><span class="small text-secondary"><?= escapar(dia_semana_treino($treino['trp_dia_semana'])) ?> · ordem <?= (int) $treino['trp_ordem'] ?></span></div><div class="d-flex gap-2"><a class="btn btn-sm btn-outline-primary btn-icone" href="<?= escapar(url('/treinos/planejados/formulario?id=' . $treino['trp_id'])) ?>"><i class="bi bi-pencil-square"></i></a><form action="<?= escapar(url('/treinos/planejados/excluir')) ?>" method="post"><?= campo_csrf() ?><input type="hidden" name="trp_id" value="<?= (int) $treino['trp_id'] ?>"><button class="btn btn-sm btn-outline-danger btn-icone" type="submit" data-confirmar="Excluir este treino planejado? O histórico realizado será preservado."><i class="bi bi-trash"></i></button></form></div></div>
<div class="table-responsive"><table class="table align-middle mb-0"><thead class="table-light"><tr><th>Exercício</th><th>Meta</th><th>Carga</th><th>Descanso</th></tr></thead><tbody><?php foreach ($treino['exercicios'] as $item): ?><tr><td><span class="fw-semibold"><?= escapar($item['exe_nome']) ?></span><?php if ($item['exp_observacoes']): ?><br><span class="small text-secondary"><?= escapar($item['exp_observacoes']) ?></span><?php endif; ?></td><td><?= (int) $item['exp_series'] ?> série(s)<?= $item['exp_repeticoes_min'] ? ' · ' . (int) $item['exp_repeticoes_min'] . ($item['exp_repeticoes_max'] && $item['exp_repeticoes_max'] != $item['exp_repeticoes_min'] ? '–' . (int) $item['exp_repeticoes_max'] : '') . ' rep.' : '' ?><?= $item['exp_duracao_segundos'] ? ' · ' . escapar(formatar_duracao_segundos($item['exp_duracao_segundos'])) : '' ?><?= $item['exp_distancia_km'] ? ' · ' . formatar_decimal($item['exp_distancia_km']) . ' km' : '' ?></td><td><?= $item['exp_carga_alvo'] === null ? '—' : formatar_decimal($item['exp_carga_alvo']) . ' kg' ?></td><td><?= escapar(formatar_duracao_segundos($item['exp_descanso_segundos'])) ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endforeach; ?></div><?php endif; ?>
